-- 0045: Lesson 9 확장 장면 영상 — 두 번째 이야기(직접 쓴 대본, 영어 문항, 자막 없음). 초안.
do $$
declare u9 uuid; v_step uuid;
begin
  select u.id into u9 from units u join books b on b.id = u.book_id where b.title = '비상교육 초5 영어' and u.no = 9;
  if u9 is null then return; end if;
  select s.id into v_step from flow_steps s join flow_lessons fl on fl.id = s.lesson_id where fl.unit_id = u9 and fl.no = 8 and s.kind = 'scene' limit 1;
  if v_step is not null and not exists (select 1 from items where step_id = v_step) then
    insert into items(unit_id, lesson, act_idx, level, template, tag, payload, status, step_id)
      values (u9, 8, 0, 'CORE', 'scene', 'listen', '{"k": "scene", "tag": "listen", "title": "A Gift for Mina", "sub": "none", "replay": 1, "scenes": [{"who": "Grandpa", "en": "Dana, what do you want for Mina''s birthday?", "ko": "다나야, 미나 생일에 뭘 주고 싶니?", "pic": "hat"}, {"who": "Dana", "en": "I want to buy a hat for her.", "ko": "모자를 사 주고 싶어요.", "pic": "hat"}, {"who": "Seller", "en": "Welcome! May I help you?", "ko": "어서 오세요! 도와드릴까요?", "pic": "hat"}, {"who": "Dana", "en": "Yes, please. I''m looking for a hat.", "ko": "네, 부탁해요. 모자를 찾고 있어요.", "pic": "hat"}, {"who": "Seller", "en": "How about this blue hat?", "ko": "이 파란 모자는 어때요?", "pic": "hat"}, {"who": "Dana", "en": "It''s nice. How much is it?", "ko": "멋지네요. 얼마예요?", "pic": "hat"}, {"who": "Seller", "en": "It''s eight thousand won.", "ko": "8,000원이에요.", "pic": "hat"}, {"who": "Dana", "en": "Oh, I want socks, too. How much are these socks?", "ko": "아, 양말도 사고 싶어요. 이 양말은 얼마예요?", "pic": "socks"}, {"who": "Seller", "en": "They''re three thousand won.", "ko": "3,000원이에요.", "pic": "socks"}, {"who": "Grandpa", "en": "Dana, look at that jacket. It''s on sale!", "ko": "다나야, 저 재킷 봐. 세일 중이야!", "pic": "jacket"}, {"who": "Seller", "en": "Yes! It was twenty thousand won. Now it''s fifteen thousand won.", "ko": "네! 20,000원이었는데 지금은 15,000원이에요.", "pic": "jacket"}, {"who": "Dana", "en": "That''s cheaper, but I only have twelve thousand won.", "ko": "더 싸졌지만, 저는 12,000원밖에 없어요.", "pic": "jacket"}, {"who": "Dana", "en": "The hat and the socks are eleven thousand won. I''ll take them.", "ko": "모자와 양말은 11,000원이네요. 그걸로 할게요.", "pic": "socks"}, {"who": "Grandpa", "en": "Good choice!", "ko": "좋은 선택이야!", "pic": "socks"}], "explain": ["[[It''s ~ won.]] 물건이 하나일 때, [[They''re ~ won.]] 물건이 여러 개일 때 써요.", "[[on sale]] 은 ''세일 중''이라는 뜻이에요.", "[[cheaper]] 는 ''더 싼''이라는 뜻이에요."], "qs": [{"q": "What does Dana want to buy for Mina?", "ans": "a hat", "wrong": ["a jacket", "shoes", "shorts"]}, {"q": "How much are the socks?", "ans": "three thousand won", "wrong": ["thirteen thousand won", "thirty thousand won", "eight thousand won"]}, {"q": "How much money does Dana have?", "ans": "twelve thousand won", "wrong": ["fifteen thousand won", "eleven thousand won", "twenty thousand won"]}]}'::jsonb, 'draft', v_step);
  end if;
end $$;
